components.content:
/* Carte principale - Sticky */
.sfc-card {
  position: sticky;
  top: 20px;
  background: #fff;
  border: 1.5px solid #e5e7eb;
  border-radius: 14px;
  padding: 24px;
  font-family: Poppins, sans-serif;
}
/* Titre principal */
.sfc-card h3 {
  font-size: 20px;
  font-weight: 700;
  color: #111827;
  margin: 0 0 4px;
}
/* Sous-titre */
.sfc-card .sfc-subtitle {
  font-size: 14px;
  color: #000;
  margin: 0 0 18px;
  line-height: 1.5;
}
/* Ligne d'information */
.sfc-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 10px;
  font-size: 13.5px;
  color: #000;
  line-height: 1.5;
}
/* Icône */
.sfc-row .sfc-ico {
  flex-shrink: 0;
  width: 20px;
  text-align: center;
  font-size: 15px;
  margin-top: 1px;
}
/* Liens */
.sfc-row a {
  color: #1a73e8;
  text-decoration: none;
}
.sfc-row a:hover {
  text-decoration: underline;
}
.sfc-row strong {
  color: #111827;
}
/* Titre section Statistiques */
.sfc-stitle {
  font-size: 18px;
  font-weight: 700;
  color: #111827;
  margin: 20px 0 12px;
  padding-top: 16px;
  border-top: 1px solid #e5e7eb;
}
.sfc-flex-box{
display:flex;

}
/* Conteneur boîtes stats */
.sfc-boxes {
  display: flex;
  white-space: normal;
  gap: 10px;
  margin-bottom: 14px;
  width:100%
}
/* Boîte stat */
.sfc-box {
  flex: 1;
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  padding: 10px;
}
/* Label stat */
.sfc-box .sfc-lbl {
  font-size: 12px;
  color: #6b7280;
  font-weight: 500;
  margin: 0 0 6px;
}
/* Valeur stat */
.sfc-box .sfc-val {
  font-size: 12px;
  font-weight: 600;
  color: #111827;
  margin: 0;
}
/* Sous-texte stat */
.sfc-box .sfc-sub {
  font-size: 11px;
  color: #9ca3af;
  font-weight: 400;
}
/* Lien voir stats */
.sfc-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #16a34a;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
}
.sfc-link:hover {
  text-decoration: underline;
}
/* Icône lien */
.sfc-link-ico {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  background: #16a34a;
  color: #fff;
  border-radius: 50%;
  font-size: 11px;
  font-weight: 700;
}
/* Responsive */
@media (max-width: 992px) {
  .sfc-card {
    position: static;
    margin-top: 20px;
  }
}
/* ---- GOUTTIERE UNIQUE DU CATALOGUE : 10px ----
   Meme mecanisme que Bootstrap (.row margin -15 / .col padding 15 = 30px),
   transpose a 10px : marge -5 et padding 5. La marge negative compense le
   padding, donc les bords exterieurs de la ligne ne bougent pas : seul l ecart
   interieur change et chaque champ gagne 10px de largeur.
   Cette page n embarque pas cf.css : la regle y est recopiee. Le :not(.cf-phone)
   exclut STRUCTURELLEMENT la boite fusionnee du telephone, dont la gouttiere
   doit rester a 0, ne pas le retirer. */
.formio-form .formio-component-columns.row:not(.cf-phone) { margin-left:-5px; margin-right:-5px; }
.formio-form .formio-component-columns.row:not(.cf-phone) > [class*=col-] { padding-left:5px; padding-right:5px; }

/* ===== Responsivite mobile (<=768px) - passeport - visuel uniquement ===== */
@media (max-width: 768px) {
  /* 1. Colonnes form.io empilees pleine largeur */
  .formio-component-columns > .row { display: block !important; margin-left: 0 !important; margin-right: 0 !important; }
  .formio-component-columns > .row > div[class*="col-"] { width: 100% !important; max-width: 100% !important; flex: 0 0 100% !important; padding-left: 6px !important; padding-right: 6px !important; margin-bottom: 2px !important; }
  /* 2. Champs pleine largeur + tactile + pas de zoom iOS (16px) */
  .formio-form .form-control, .formio-form .choices, .formio-form .choices__inner, .formio-form select, .formio-form input:not([type=checkbox]):not([type=radio]), .formio-form textarea { width: 100% !important; max-width: 100% !important; font-size: 16px !important; box-sizing: border-box !important; }
  .formio-form .form-control, .formio-form .choices__inner, .formio-form select { min-height: 44px !important; }
  /* 3. Panels / fieldsets / cartes : padding reduit */
  .formio-form .card-body, .formio-form .panel-body, .formio-form fieldset { padding: 12px !important; }
  .formio-form .card, .formio-form .panel, .formio-form fieldset { margin-bottom: 12px !important; }
  /* 4. Titres legerement reduits */
  .formio-form h1 { font-size: 22px !important; } .formio-form h2 { font-size: 19px !important; } .formio-form h3 { font-size: 16px !important; }
  /* 5. Cartes info (delai/cout/validite) + stats sidebar empilees */
  .info-cards-container > div { flex-direction: column !important; flex-wrap: wrap !important; gap: 10px !important; }
  .sfc-boxes, .sfc-flex-box { flex-direction: column !important; }
  .sfc-card { position: static !important; margin-top: 16px !important; }
  /* 6. Navigation wizard : boutons empiles pleine largeur, breadcrumb scrollable */
  .formio-wizard-nav-container { display: flex !important; flex-wrap: wrap !important; gap: 8px !important; }
  .formio-wizard-nav-container li { flex: 1 1 auto !important; list-style: none !important; }
  .formio-wizard-nav-container .btn, .btn-wizard-nav-previous, .btn-wizard-nav-next, .btn-wizard-nav-submit, .btn-wizard-nav-cancel { width: 100% !important; padding: 12px !important; }
  .pagination { overflow-x: auto !important; flex-wrap: nowrap !important; -webkit-overflow-scrolling: touch !important; }
  /* 7. Recap : tableau scrollable et lisible */
  #recapDisplay { overflow-x: auto !important; -webkit-overflow-scrolling: touch !important; }
  .formio-form table { width: 100% !important; font-size: 13px !important; }
  .formio-form table td, .formio-form table th { padding: 6px !important; word-break: break-word !important; }
  /* 8. Pas de debordement horizontal */
  .formio-form, .formio-form .wizard-page, .formio-component-panel { overflow-x: hidden !important; }
  /* 9. Radios inline lisibles */
  .formio-form .form-check-inline { margin-right: 14px !important; margin-bottom: 4px !important; }
  /* 10. Cartes info Delai/Cout/Validite (composant html2) : empiler */
  .formio-component-html2 > div { flex-wrap: wrap !important; gap: 12px !important; }
  .formio-component-html2 > div > div { flex: 1 1 100% !important; min-width: 0 !important; padding: 16px !important; }
  /* 11. Blocs HTML bruts : titres et paddings inline reduits */
  [style*="font-size:22px"] { font-size: 18px !important; }
  [style*="font-size:20px"] { font-size: 17px !important; }
  [style*="font-size:18px"] { font-size: 16px !important; }
  [style*="padding:25px"], [style*="padding: 25px"] { padding: 14px !important; }
  /* 12. Bouton Faire une demande pleine largeur */
  .formio-component-startButton .btn, .formio-component-startButton button { width: 100% !important; padding: 12px !important; font-size: 16px !important; }
  /* 13. Images dans blocs HTML : ne pas deborder */
  .formio-form img { max-width: 100% !important; height: auto !important; }
  /* 14. Colonne principale : masquer la sidebar vide */
  .formio-component-mainLayout > .row > div:empty { display: none !important; }
  /* 15. Etapes numerotees : garder l alignement, autoriser le retour a la ligne */
  [style*="display:flex;align-items:flex-start"] { flex-wrap: nowrap !important; }
  [style*="display:flex;align-items:flex-start"] > div:last-child { min-width: 0 !important; word-break: break-word !important; }
}
/* ===== Tres petits ecrans (<=480px) : paddings et titres plus serres ===== */
@media (max-width: 480px) {
  [style*="padding:25px"], [style*="padding: 25px"] { padding: 12px !important; }
  [style*="padding:20px 24px"] { padding: 14px !important; }
  [style*="padding:12px 16px"] { padding: 10px 12px !important; }
  [style*="font-size:22px"] { font-size: 17px !important; }
  [style*="font-size:20px"] { font-size: 15px !important; }
  .formio-component-html2 > div > div h3 { font-size: 14px !important; }
  .formio-component-html2 > div > div p { font-size: 13px !important; }
  .formio-form h1 { font-size: 20px !important; } .formio-form h2 { font-size: 17px !important; }
}
/* Tres petits ecrans (<=380px) : gap dates reduit */
@media (max-width: 380px) {
  [class*="formio-component-"] .row { gap: 4px !important; }
}

